  var WHOLE = {"งาน": "Job", "ซ่อน": "Hide", "ตอนนี้": "Now", "ทั้งหมด": "All", "ปิด": "Off", "ยกเลิก": "Cancel", "ล้าง": "Clear", "วิดีโอ": "Videos", "สร้าง": "Create", "หมดเวลา": "Timed out", "อีก": "more", "เก็บ": "Archive", "เปิด": "On", "แก้ไข": "Edit", "แสดง": "Show", "ใช่": "yes", "ไม่": "no"};    // short words: only when they are the whole text, never inside other text
