      + 'border-radius:999px;background:rgba(15,23,42,.86);border:1px solid rgba(148,163,184,.3);box-shadow:0 6px 18px rgba(0,0,0,.25);opacity:.8;transition:opacity .15s;'
      + 'font:600 11px/1 Inter,"Noto Sans Thai","Segoe UI",Tahoma,sans-serif;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}'
      + '#qwen-lang-switch:hover,#qwen-lang-switch:focus-within{opacity:1}'
      + '#qwen-lang-switch button{all:unset;cursor:pointer;padding:5px 9px;border-radius:999px;color:#94a3b8}'
      + '#qwen-lang-switch button:hover{color:#e2e8f0}'
      + '#qwen-lang-switch button[aria-pressed="true"]{background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;cursor:default}'
      + '#qwen-lang-switch button:focus-visible{outline:2px solid #a78bfa;outline-offset:1px}'
      + '@media print{#qwen-lang-switch{display:none}}';
